def remove_adjacent_duplicates(s):
    """反复删除相邻重复对。"""
    result = []
    for i in range(len(s)):
        if i > 0 and result[-1] == s[i]:
            result.pop()
        else:
            result.append(s[i])
    return "".join(result)
```

